action.command:
cat > /tmp/cdiff.php <<'EOF'
<?php
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$active = \Drupal::config('admin_toolbar.settings')->getRawData();
$sync = $storage->read('admin_toolbar.settings');
echo "--- sync ---\n"; print_r($sync);
echo "--- active ---\n"; print_r($active);
EOF
cd /workspace && cp /tmp/cdiff.php /workspace/cdiff_tmp.php && su ddevuser -c "ddev drush php:script cdiff_tmp.php" 2>&1 | tail -30; rm -f /workspace/cdiff_tmp.php

